import com.comsol.model.*; import com.comsol.model.util.*;
public class InspectMeshModel{public static void main(String[]a)throws Exception{ModelUtil.initStandalone(true);Model m=ModelUtil.load("m","D:\\comsol_ao_run\\convergence\\Wap_6um_coupled_eigen.mph");System.out.println("MESHES="+java.util.Arrays.toString(m.mesh().tags()));for(String mt:m.mesh().tags()){System.out.println("MESH "+mt+" FEATURES="+java.util.Arrays.toString(m.mesh(mt).feature().tags()));for(String t:m.mesh(mt).feature().tags()){try{System.out.println(t+" hmax="+m.mesh(mt).feature(t).getString("hmax")+" hmin="+m.mesh(mt).feature(t).getString("hmin"));}catch(Exception e){}}}System.out.println("STUDIES="+java.util.Arrays.toString(m.study().tags()));for(String s:m.study().tags())System.out.println(s+" "+java.util.Arrays.toString(m.study(s).feature().tags()));ModelUtil.disconnect();}}
